function providerById(id){return S.integrations.find(c=>c.id===id)||S.connections.find(c=>c.id===id)||DEMO_CONNECTORS.find(c=>c.id===id)||null;}
function providerName(id){return SHORT[id]||providerById(id)?.name||id;}
function providerIcon(id){const file=PROVIDER_LOGOS[id];const p=providerById(id);const initials=((p?.initials||providerName(id)).match(/[A-Za-z0-9+]+/g)||['?']).slice(0,2).join('').slice(0,4);if(file)return `<span class="provider-icon ${esc(id)}" aria-hidden="true"><img class="connector-logo" src="/assets/${esc(file)}" alt=""></span>`;return `<span class="provider-icon ${esc(id)} fallback" aria-hidden="true">${esc(initials)}</span>`;}
function brand(){return `<div class="brand"><img src="/assets/circlelogic-logo-original.svg" alt="Circle Logic logo" width="38" height="38"><div class="brand-copy"><strong>CircleLogic</strong><span class="sub">REAL ESTATE HUB</span></div></div>`;}
function statusMarkup(status){const labels={not_connected:'Not connected',configured:'Credentials saved',authorised:'Ready to sync',connected:'Connected',error:'Needs attention',stale:'Stale snapshot',disconnected:'Disconnected',restricted:'Access restricted',example:'Preview data'};return `<span class="status ${esc(status)}"><span class="dot"></span>${esc(labels[status]||status)}</span>`;}
function relative(ts){if(!ts)return 'Never synced';const m=Math.max(0,Math.floor((Date.now()/1000-ts)/60));return m<1?'Just now':m<60?`${m} min ago`:m<1440?`${Math.floor(m/60)} hr ago`:`${Math.floor(m/1440)} days ago`;}
function dateObj(value,zone='UTC'){if(!value)return null;const raw=String(value);const isOffset=/(Z|[+-]\d\d:\d\d)$/.test(raw);const d=new Date(!isOffset&&['UTC','Etc/UTC'].includes(zone)?raw+'Z':raw);return Number.isNaN(d.getTime())?null:d;}
function fmtDate(value,options={}){const d=value instanceof Date?value:dateObj(value);return d?new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Sydney',...options}).format(d):'Time unavailable';}
function safeJson(value){return esc(JSON.stringify(value,null,2));}
async function api(path,method='GET',body){
 if(S.preview)return window.previewApi(path,method,body);
 const opts={method,credentials:'same-origin',headers:{}};
 if(method!=='GET'){opts.headers={'Content-Type':'application/json','X-CSRF-Token':S.csrf};opts.body=JSON.stringify(body||{});}
 let response;try{response=await fetch('/api'+path,opts);}catch{throw Error('The server is unavailable. Start the application with python run.py, then open http://localhost:8000.');}
 let data;try{data=await response.json();}catch{throw Error('The backend returned an unreadable response. Check that the application server is running.');}
 if(!response.ok){const error=Error(Array.isArray(data.detail)?data.detail.map(x=>x.msg).join('; '):data.detail||'This request could not be completed.');error.status=response.status;
  if(response.status===401&&!path.startsWith('/auth/')){S.user=null;S.data=null;S.auth='login';closeModal();renderAuth();}
  throw error;
 }
 return data;
}
function toast(message,error=false){$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${esc(message)}</div>`;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',7000);}
function formError(form,message){let box=$('.error-box',form);if(!box){box=document.createElement('div');box.className='error-box';box.setAttribute('role','alert');form.prepend(box);}box.textContent=message?.message||String(message);box.scrollIntoView({block:'nearest'});}
function modal(title,body,wide=false){
 const previous=$('#active-dialog');if(previous)previous.close();
 if(!S.lastFocus)S.lastFocus=document.activeElement;
 $('#modal-root').innerHTML=`<dialog id="active-dialog" class="dialog ${wide?'wide':''}" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close',20)}</button></header><div class="modal-body">${body}</div></dialog>`;
 const el=$('#active-dialog');el.addEventListener('cancel',e=>{e.preventDefault();closeModal();});el.showModal();
 el.addEventListener('click',e=>{if(e.target===el){const r=el.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
}
function closeModal(){const el=$('#active-dialog');if(el)el.close();$('#modal-root').innerHTML='';if(S.lastFocus?.isConnected)S.lastFocus.focus();S.lastFocus=null;S.pending=null;}
function field(key,label,type='text',help='',attributes=''){
 const secret=type==='password';return `<div class="field"><label for="f-${esc(key)}">${esc(label)}</label><div class="${secret?'input-wrap':''}"><input id="f-${esc(key)}" name="${esc(key)}" type="${esc(type)}" required ${attributes}>${secret?`<button type="button" class="icon-btn" data-action="show-secret" data-target="f-${esc(key)}" aria-label="Show ${esc(label.toLowerCase())}">${icon('eye',16)}</button>`:''}</div>${help?`<small>${esc(help)}</small>`:''}</div>`;
}
function navigate(route){S.route=route==='integrations'?'integrations':'dashboard';closeModal();if(location.hash===`#${S.route}`)render();else location.hash=S.route;}
function shell(){
 const username=S.user?.username||S.user?.email||'Account';
 const collapsedClass=S.sidebarCollapsed?'collapsed':'';
 $('#app').innerHTML=`<aside class="sidebar ${collapsedClass}" aria-label="Main navigation"><div class="sidebar-top"><div class="sidebar-brand-row">${brand()}<button class="icon-btn collapse-toggle" data-action="collapse-sidebar" aria-label="${S.sidebarCollapsed?'Expand':'Collapse'} navigation">${icon('chevron',16)}</button></div><nav class="sidebar-nav" aria-label="Workspace pages">
 <button class="nav-button ${S.route==='dashboard'?'active':''}" data-nav="dashboard" ${S.route==='dashboard'?'aria-current="page"':''}><span class="nav-icon">${icon('grid',18)}</span><span class="nav-label">Dashboard</span></button>
 <button class="nav-button ${S.route==='integrations'?'active':''}" data-nav="integrations" ${S.route==='integrations'?'aria-current="page"':''}><span class="nav-icon">${icon('plug',19)}</span><span class="nav-label">API Connections</span></button></nav></div>
 <div class="sidebar-bottom"><div class="sidebar-help"><div class="help-icon">${icon('spark',20)}</div><div class="sidebar-help-copy"><h3>Connected systems, clearer decisions.</h3><p>Connected systems and a clearer executive view — with live calendar support where enabled.</p><button class="text-btn" data-action="guide" data-provider="agentbox">Connection guides ${icon('arrow',13)}</button></div></div>
 <div class="profile"><button class="avatar" style="border:0" data-action="security" aria-label="Account security">${esc(username[0]?.toUpperCase()||'A')}</button><div class="profile-copy"><div class="name">${esc(username)}</div><div class="caption">${S.preview?'Design preview':esc(S.user?.agency||'Your workspace')}</div></div><button class="icon-btn" data-action="logout" aria-label="Sign out">${icon('logout',17)}</button></div></div></aside>
 <main class="main ${collapsedClass}"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="toggle-menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu',18)}</button><div class="breadcrumb"><span>Workspace</span>${icon('chevron',10)}<strong>Real Estate Hub</strong></div></div><div class="topbar-right"><span class="workspace-badge">Connection overview</span><button class="icon-btn" data-action="connection-health" aria-label="Connection status">${icon('bell',18)}</button><button class="avatar" style="border:0" data-action="security" aria-label="Open account">${esc(username[0]?.toUpperCase()||'A')}</button></div></header>
 ${S.preview?`<div class="preview-strip"><div><strong>${S.example?'EXAMPLE DATA':'INTERACTIVE DESIGN PREVIEW'}</strong> &nbsp; ${S.example?'Illustrative numbers and records for presentation. Google Calendar remains the only live module.':'No real accounts or credentials. Login and 2FA are simulated here.'}</div><div class="segmented" aria-label="Preview data"><button data-action="preview-empty" class="${!S.example?'active':''}">Empty dashboard</button><button data-action="preview-example" class="${S.example?'active':''}">Example data</button></div></div>`:''}
 <div class="content" id="page"><div class="loading">Loading your workspace...</div></div></main>`;
}
function footer(){return `<footer class="footer"><span>${icon(S.preview?'eye':'shield',12)}${S.preview?'Synthetic design preview. No provider requests.':'Connection-ready workspace with live calendar support and refined preview data.'}</span><span>CircleLogic OS <strong>v14</strong> &middot; Real Estate Hub</span></footer>`;}
function heading(title,description){const times=S.connections.filter(c=>c.status==='connected').map(c=>c.last_success).filter(Boolean);const latest=times.length?Math.max(...times):null;
 return `<div class="heading"><div><div class="eyebrow">CIRCLELOGIC / REAL ESTATE HUB</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="heading-actions"><span class="snapshot-label">${icon('clock',13)}${S.example?'Illustrative snapshot':latest?'Last live calendar sync '+relative(latest):'Demo data with no live calendar connected'}</span><button class="btn" data-action="refresh">${icon('refresh',14)}${S.preview?'Refresh view':'Refresh data'}</button></div></div>`;
}
function sourceTile(c){return `<button class="source-tile card interactive" data-connect="${esc(c.id)}" aria-label="${esc(SHORT[c.id])}: ${esc(c.status.replaceAll('_',' '))}">${providerIcon(c.id)}<div class="source-meta"><div class="source-name">${esc(SHORT[c.id])}</div><div class="source-description">${esc(c.id==='google'?'Live calendar sync':'Connected data source')}</div>${statusMarkup(c.status)}</div><span class="tile-arrow">${icon('chevron',12)}</span></button>`;}
function metricCard(m){const missing=m.value===null||m.value===undefined;const value=missing?'&mdash;':new Intl.NumberFormat('en-AU').format(m.value);const series=(m.series||[]).slice(0,7);return `<article class="metric card interactive metric-${esc(m.provider)}" data-metric="${esc(m.id)}"><div class="metric-head"><span class="metric-icon">${iconFor(m.icon)}</span><span class="metric-title">${esc(m.title)}</span></div><div class="metric-value ${missing?'missing':''}">${value}</div>
 ${m.delta!==null&&m.delta!==undefined?`<div class="metric-trend ${m.delta<0?'negative':''}">${m.delta<0?'&#8595;':'&#8593;'} ${Math.abs(m.delta)}% <span class="muted">vs last period</span></div>`:`<div class="data-note">${missing?(m.mode==='restricted'?'Access restricted':'No data yet'):m.mode==='stale'?'Stale imported snapshot':m.mode==='example'?'Illustrative data':'Latest imported snapshot'}</div>`}
 ${series.length?`<div class="metric-chart" aria-hidden="true">${series.map(v=>`<span style="height:${Math.max(22,Math.min(100,Number(v)||0))}%"></span>`).join('')}</div>`:''}
 <div class="metric-footer"><button class="text-btn metric-connect" data-action="metric-info" data-id="${esc(m.id)}">${missing?'What connects here?':'Data details'} ${icon('chevron',10)}</button><span class="provider-label">${esc(SHORT[m.provider])}</span></div></article>`;}
function emptyPanel(title,text,provider,ic='chart'){return `<div class="empty-panel"><div class="empty-illustration">${icon(ic,25)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p><button class="text-btn" data-connect="${provider}">Connect ${esc(SHORT[provider])} ${icon('arrow',13)}</button></div>`;}
function reportSummary(r){const t=r.totals||{};const parts=[];if(t.page_views!==null&&t.page_views!==undefined)parts.push(Number(t.page_views).toLocaleString('en-AU')+' views');if(t.email_enquiries!==null&&t.email_enquiries!==undefined)parts.push(Number(t.email_enquiries).toLocaleString('en-AU')+' email enquiries');if(t.saves!==null&&t.saves!==undefined)parts.push(Number(t.saves).toLocaleString('en-AU')+' saves');return parts.length?parts.join(' / ')+' (report period)':'Imported listing-performance report';}

function scoreColor(score){const value=Math.max(0,Math.min(100,Number(score)||0));const hue=Math.round((value/100)*120);return `hsl(${hue} 65% 45%)`;}
function initials(name){return String(name||'').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'RE';}
function metricValue(id){const item=S.data?.metrics?.find(m=>m.id===id);return item?.value??null;}
function statValue(id){const value=metricValue(id);return value===null?'—':new Intl.NumberFormat('en-AU').format(value);}
function sourceChips(names){return `<div class="source-chips">${names.map(n=>`<span>${esc(n)}</span>`).join('')}</div>`;}
function summaryBar(label,value,accent,sub=''){return `<div class="summary-pill"><span class="summary-label">${esc(label)}</span><strong class="summary-value">${esc(value)}</strong>${sub?`<span class="summary-sub">${esc(sub)}</span>`:''}<i class="summary-accent ${esc(accent)}"></i></div>`;}
function financialPanel(){const f=DEMO_FINANCIALS;return `<section class="panel card interactive panel-financial" data-action="open-panel" data-panel="financial"><div class="panel-head"><div><h2>Financial performance</h2><p class="subtitle">Revenue, commission and recurring management income</p></div><span class="module-badge">${esc(DEMO_KPIS.revenue)}</span></div>${sourceChips(['Xero','Agentbox','PropertyMe'])}<div class="financial-preview"><div><span>Revenue MTD</span><strong>${esc(DEMO_KPIS.revenue)}</strong><em>89.5% of monthly target</em></div><div class="spark-columns">${f.months.map(x=>`<i style="height:${Math.max(25,Math.round(x.value/3.2))}%"></i>`).join('')}</div></div><div class="mini-kpis"><span><b>${esc(f.breakdown[0][1])}</b>Sales GCI</span><span><b>${esc(f.breakdown[1][1])}</b>PM fees</span><span><b>${esc(DEMO_KPIS.pipeline)}</b>Pipeline GCI</span></div><div class="panel-foot">Open for monthly trend, revenue mix and target tracking.</div></section>`;}
function pipelinePanel(){return `<section class="panel card interactive panel-pipeline" data-action="open-panel" data-panel="pipeline"><div class="panel-head"><div><h2>Sales pipeline & transactions</h2><p class="subtitle">Appraisals through settlement, including expected commission</p></div><span class="module-badge">${esc(DEMO_KPIS.pipeline)}</span></div>${sourceChips(['Agentbox','Vault','Rex','Realtair'])}<div class="pipeline-preview">${DEMO_PIPELINE.slice(0,4).map((r,i)=>`<div><span class="stage-dot s${i}"></span><span><strong>${esc(r.stage)}</strong><small>${esc(r.deals)} opportunities · ${esc(r.volume)}</small></span><b>${esc(r.gci)}</b></div>`).join('')}</div><div class="panel-foot">Open for the full opportunity funnel and transaction stages.</div></section>`;}
function enquiriesPanel(){return `<section class="panel card interactive panel-enquiries" data-action="open-panel" data-panel="enquiries"><div class="panel-head"><div><h2>Enquiries & leads</h2><p class="subtitle">New demand across portals, websites and database campaigns</p></div><span class="module-badge">${esc(statValue('enquiries'))}</span></div>${sourceChips(['REA Ignite','Domain','Websites'])}<div class="compact-list">${DEMO_ENQUIRIES.slice(0,4).map(r=>`<div class="compact-row"><span class="person-avatar">${esc(initials(r.name))}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.source)} · ${esc(r.intent)}</small></span><b>${esc(r.received)}</b></div>`).join('')}</div><div class="panel-foot">Open to review more leads, sources and intent signals.</div></section>`;}
function contactsPanel(){const rows=DEMO_CONTACTS.slice(0,4);return `<section class="panel card interactive panel-contacts" data-action="open-panel" data-panel="contacts"><div class="panel-head"><div><h2>Contacts & CRM</h2><p class="subtitle">Buyer, vendor, landlord and past-client relationships</p></div><span class="module-badge">${esc(statValue('contacts'))}</span></div>${sourceChips(['Agentbox','Vault','Rex'])}<div class="list-stack">${rows.map((r,i)=>`<button class="person-row" data-action="demo-record" data-kind="contacts" data-index="${i}"><span class="person-avatar teal">${esc(initials(r.title))}</span><span class="person-copy"><strong>${esc(r.title)}</strong><span>${esc(r.role)} · ${esc(r.suburb)}</span></span><span class="person-meta"><em>${esc(r.last_touch)}</em><b>${esc(r.status)}</b></span></button>`).join('')}</div><div class="panel-foot">Open for the extended CRM contact view.</div></section>`;}
function listingsPanel(){const rows=DEMO_LISTINGS.slice(0,4);return `<section class="panel card interactive panel-listings" data-action="open-panel" data-panel="listings"><div class="panel-head"><div><h2>Listings & campaigns</h2><p class="subtitle">Active stock, campaign stage and seller activity</p></div><span class="module-badge">${esc(statValue('listings'))}</span></div>${sourceChips(['Agentbox','REA Ignite','Domain'])}<div class="list-stack">${rows.map((r,i)=>`<button class="listing-row" data-action="demo-record" data-kind="listings" data-index="${i}"><span class="listing-copy"><strong>${esc(r.title)}</strong><span>${esc(r.suburb)} · ${esc(r.summary)}</span></span><span class="listing-meta"><b>${esc(r.price)}</b><em>${esc(r.stage)}</em></span></button>`).join('')}</div><div class="panel-foot">Open for all active and pre-market listing detail.</div></section>`;}
function buyersPanel(){const rows=DEMO_BUYERS.slice(0,4);return `<section class="panel card interactive panel-buyers" data-action="open-panel" data-panel="buyers"><div class="panel-head"><div><h2>Buyer engagement</h2><p class="subtitle">Illustrative buyer intent, matching and next-best action</p></div><span class="module-badge">${esc(statValue('buyers'))}</span></div>${sourceChips(['REA Ignite','Agentbox','ActivePipe'])}<div class="list-stack">${rows.map((r,i)=>`<button class="buyer-score-row" data-action="demo-record" data-kind="buyers" data-index="${i}"><span class="person-copy"><strong>${esc(r.title)}</strong><span>${esc(r.interest)} · ${esc(r.budget)}</span></span><span class="score-column"><span class="score-track"><i style="width:${Math.max(0,Math.min(100,Number(r.score)||0))}%;background:${scoreColor(r.score)}"></i></span><b style="color:${scoreColor(r.score)}">${esc(r.score)}</b></span></button>`).join('')}</div><div class="panel-foot">Green = higher illustrative intent. Red = lower engagement.</div></section>`;}
function propertyManagementPanel(){return `<section class="panel card interactive panel-pm" data-action="open-panel" data-panel="propertymgmt"><div class="panel-head"><div><h2>Property management</h2><p class="subtitle">Portfolio health, occupancy, arrears and operational workload</p></div><span class="module-badge">${esc(DEMO_KPIS.managed)}</span></div>${sourceChips(['PropertyMe','Property Tree','Console'])}<div class="pm-grid">${DEMO_PM_STATS.slice(0,4).map(x=>`<div><span>${esc(x.label)}</span><strong>${esc(x.value)}</strong><small>${esc(x.detail)}</small></div>`).join('')}</div><div class="panel-foot">Open for portfolio, maintenance, inspections and lease-renewal detail.</div></section>`;}
function marketPanel(d){const data=d.market_activity;const rows=(data.rows||[]).slice(0,4);return `<section class="panel card interactive panel-market" data-action="open-panel" data-panel="market"><div class="panel-head"><div><h2>Market & property intelligence</h2><p class="subtitle">Local movement, values, comparable sales and suburb signals</p></div><span class="module-badge soft">6 suburbs</span></div>${sourceChips(['RP Data','Pricefinder','Proping'])}<div class="market-suburbs">${DEMO_MARKET_SUBURBS.slice(0,4).map(r=>`<div><span><strong>${esc(r.suburb)}</strong><small>${esc(r.dom)} DOM · ${esc(r.clearance)} clearance</small></span><b>${esc(r.median)}</b><em>${esc(r.change)}</em></div>`).join('')}</div>${rows.length?`<div class="market-alert-strip">${rows.slice(0,3).map(r=>`<span><b>${esc(r.count)}</b>${esc(r.title)}</span>`).join('')}</div>`:''}<div class="panel-foot">Open for suburb comparisons, weekly market activity and trend charts.</div></section>`;}
function marketingPanel(){return `<section class="panel card interactive panel-marketing" data-action="open-panel" data-panel="marketing"><div class="panel-head"><div><h2>Marketing performance</h2><p class="subtitle">Portal views, saves, enquiries, spend and campaign efficiency</p></div><span class="module-badge soft">6 campaigns</span></div>${sourceChips(['REA Ignite','Domain','Realhub','ActivePipe'])}<div class="campaign-preview">${DEMO_MARKETING.slice(0,4).map(r=>`<div><span><strong>${esc(r.campaign)}</strong><small>${esc(r.views)} views · ${esc(r.saves)} saves</small></span><b>${esc(r.enquiries)} leads</b></div>`).join('')}</div><div class="panel-foot">Open to compare campaign performance and cost per lead.</div></section>`;}
function calendarPanel(d){const data=d.calendar;let content;const max=Date.now()+S.days*86400000;const rows=(data.rows||[]).map((r,i)=>({...r,index:i})).filter(r=>{const start=dateObj(r.start,r.timezone);return start&&start.getTime()<=max;});const sources=(data.sources||[]);const sourceLabel=sources.length?sources.join(' + '):'Google Calendar';if(data.total!==null){content=rows.length?`<div class="event-list calendar-wide-list">${rows.slice(0,6).map(r=>{const dt=dateObj(r.start,r.timezone);return `<button class="event" data-action="record" data-panel="calendar" data-index="${r.index}"><span class="date-tile"><span>${esc(fmtDate(dt,{weekday:'short'}))}</span><b>${esc(fmtDate(dt,{day:'numeric'}))}</b></span><span class="event-title">${esc(r.title)}<span class="event-time">${r.all_day?'All day':esc(fmtDate(dt,{hour:'numeric',minute:'2-digit'}))} · ${esc(r.location||r.calendar_source||'Calendar event')}</span></span><span class="chevron">${icon('chevron',12)}</span></button>`;}).join('')}</div><div class="panel-foot">Your private calendar · ${esc(sourceLabel)} · Sydney time</div>`:`<div class="empty-panel"><div class="empty-illustration">${icon('calendar',25)}</div><h3>No upcoming events</h3><p>No imported events within the next ${S.days} days. Your live Google Calendar remains untouched.</p></div>`;}else content=emptyPanel('Make room for what matters','Connect Google Calendar to see upcoming appointments. Visible only to your login.','google','calendar');return `<section class="panel card interactive panel-calendar" data-action="open-panel" data-panel="calendar"><div class="panel-head"><div><h2>Diary, tasks & appointments</h2><p class="subtitle">${data.mode==='stale'?'Stale snapshot · needs refresh':esc(sourceLabel)+' · live Google Calendar'}</p></div><select class="btn" style="font-size:10px;padding:5px 9px;min-height:30px" id="calendar-window" aria-label="Calendar time window"><option value="7" ${S.days===7?'selected':''}>7 days</option><option value="30" ${S.days===30?'selected':''}>30 days</option></select></div>${sourceChips(['Google Calendar','CRM tasks'])}${content}</section>`;}
function newModulePanel(){return `<section class="panel new-module-panel" data-action="new-module"><div class="new-module-mark">${icon('plus',22)}</div><div class="new-module-copy"><div class="eyebrow">CUSTOMISE YOUR HUB</div><h2>New modules</h2><p>Add another operational view to Real Estate Hub when you are ready. This area is a placeholder for a future module builder.</p><div class="new-module-tags"><span>Compliance</span><span>Recruitment</span><span>AI workflows</span><span>Custom KPI</span></div></div><button class="btn soft" data-action="new-module">Add module ${icon('plus',13)}</button></section>`;}
function overviewPanel(){return `<section class="overview-card card"><div class="overview-copy"><div><div class="eyebrow">EXECUTIVE SNAPSHOT</div><h2>Real Estate Hub</h2><p>The first five numbers an agency leader should see: revenue, future commission, lead flow, active stock and recurring portfolio scale.</p></div><div class="summary-grid">${[
 ['Revenue MTD',DEMO_KPIS.revenue,'teal','89.5% of target'],
 ['Pipeline GCI',DEMO_KPIS.pipeline,'blue','expected commission'],
 ['New enquiries',statValue('enquiries'),'green','current reporting window'],
 ['Active listings',statValue('listings'),'gold','live / available stock'],
 ['Properties managed',DEMO_KPIS.managed,'plum','recurring portfolio'],
].map(([label,value,accent,sub])=>summaryBar(label,value,accent,sub)).join('')}</div></div></section>`;}
function dashboardPage(d){return heading('Real Estate Hub','Ten unified views across financials, sales, leads, CRM, listings, buyers, property management, market intelligence, marketing and diary activity.')+`${overviewPanel()}<div class="hub-grid">${financialPanel()}${pipelinePanel()}${enquiriesPanel()}${contactsPanel()}${listingsPanel()}${buyersPanel()}${propertyManagementPanel()}${marketPanel(d)}${marketingPanel()}${calendarPanel(d)}${newModulePanel()}</div>`+`<section class="callout"><div class="callout-icon">${icon('spark',20)}</div><div><h3>Connected executive view.</h3><p>The dashboard combines refined preview data with live calendar support and a broader API connection catalogue.</p></div><div class="callout-actions"><button class="text-btn" data-nav="integrations">Explore connections ${icon('arrow',14)}</button></div></section>`+footer();}
function demoConnectorIcon(c){return `<span class="demo-provider-icon tone-${esc(c.tone)}" aria-hidden="true">${esc(c.short)}</span>`;}
function openDemoConnector(id){const c=DEMO_CONNECTORS.find(x=>x.id===id);if(!c)return;modal(c.name,`<div class="modal-provider">${demoConnectorIcon(c)}<div><h3>${esc(c.name)}</h3><p>${esc(c.category)} · connector</p></div></div><p class="intro">${esc(c.description)}</p><div class="info-banner neutral">${icon('info',18)}<span>Connection support for this system can be extended over time. This modal simply summarises the potential data contribution.</span></div><h3 style="margin:18px 0 10px">Data this connector can contribute</h3><div class="feed-chip-list">${c.feeds.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="form-actions"><button class="btn primary" data-action="close-modal">Close</button></div>`,true);}
function integrationsPage(){const all=S.integrations.length?S.integrations:S.connections;const connected=all.filter(c=>c.has_credentials||c.status==='connected'||c.status==='authorised').length;const live=all.filter(c=>c.status==='connected'||c.status==='authorised').length;return heading('API Connections','A single, consistent catalogue of the platforms that can be connected into Real Estate Hub.')+pilotBanner()+`<section class="connections-overview card"><div class="connections-overview-copy"><div><h2>Connection catalogue</h2><p class="subtitle">One place to manage all connectors, with consistent setup and cleaner branding.</p></div><div class="connections-overview-metrics"><span class="provider-label">${connected} configured</span><span class="provider-label">${live} active</span><span class="provider-label">${all.length} available</span></div></div><div class="info-banner">${icon('plug',17)}<span>Every listed API can now be connected here. Google Calendar remains fully live, while additional connected systems can be credentialled and managed consistently from the same view.</span></div></section><div class="unified-connector-grid">${all.map(c=>`<article class="unified-connector-card card" data-provider-row="${esc(c.id)}"><div class="unified-connector-head">${providerIcon(c.id)}<div class="unified-connector-copy"><strong>${esc(c.name)}</strong><small>${esc(c.category)}</small></div>${statusMarkup(c.status)}</div><p class="unified-connector-description">${esc(c.description||DESCRIPTIONS[c.id]||'Connect this system to Real Estate Hub.')}</p><div class="connector-meta-row"><span>${(c.kinds||[]).length?(c.kinds.join(' · ').replaceAll('_',' ')):'Connection ready'}</span>${c.docs?`<a href="${esc(c.docs)}" target="_blank" rel="noopener noreferrer">Docs ${icon('external',12)}</a>`:''}</div><div class="connector-actions"><button class="btn ${c.has_credentials?'':'soft'}" data-connect="${esc(c.id)}">${c.has_credentials?'Manage':'Connect'} ${icon(c.has_credentials?'chevron':'plus',12)}</button>${window.BRAIN_GUIDES?.[c.id]?`<button class="text-btn" data-action="guide" data-provider="${esc(c.id)}">Setup guide ${icon('chevron',12)}</button>`:''}</div></article>`).join('')}</div><section class="callout"><div class="callout-icon">${icon('shield',20)}</div><div><h3>Uniform connection experience.</h3><p>All connectors now sit in one catalogue with logos, consistent controls and a cleaner visual hierarchy.</p></div><div class="callout-actions"><button class="text-btn" data-action="connection-health">View connection readiness ${icon('arrow',13)}</button></div></section>`+footer();}
async function render(){
 if(!S.user)return renderAuth();
 S.route=location.hash.startsWith('#integrations')?'integrations':'dashboard';const requestId=++S.request;shell();
 try{const [data,connections,integrations,runtime]=await Promise.all([api('/brain/dashboard'),api('/brain/connections'),api('/integrations'),S.preview?Promise.resolve(null):api('/pilot/readiness')]);if(requestId!==S.request||!S.user)return;S.data=data;S.connections=connections.connections;S.integrations=integrations.integrations;S.runtime=runtime;S.example=!!(S.preview&&window.previewState?.example);shell();$('#page').innerHTML=S.route==='integrations'?integrationsPage():dashboardPage(data);
  const oauthProvider='google';
  if(location.hash.includes('oauth=success')){history.replaceState(null,'','#integrations');toast(SHORT[oauthProvider]+' authorised. Open it, then select Test and sync to import your calendar.');}
  if(location.hash.includes('oauth=failed')){history.replaceState(null,'','#integrations');toast(SHORT[oauthProvider]+' could not complete authorisation. Open Connection checks for the saved error.',true);}
  if(location.hash.includes('oauth=denied')){history.replaceState(null,'','#integrations');toast('Authorisation was cancelled. No calendar data was imported.',true);}
 }catch(e){if(!S.user)return;$('#page').innerHTML=`<section class="card panel"><h2>We could not load this workspace</h2><p class="intro" style="margin:15px 0">${esc(e.message)}</p><button class="btn" data-action="reload">Try again</button></section>`;}
}
function authBody(){
 if(S.recoveries.length){return `<div class="auth-icon">${icon('shield',23)}</div><h1>Keep a way back in.</h1><p class="intro">Save these one-use recovery codes somewhere private, away from this device. They are shown once.</p><div class="recoveries">${S.recoveries.map(r=>`<code>${esc(r)}</code>`).join('')}</div><button class="btn full" data-action="copy-recoveries">${icon('copy',14)}Copy recovery codes</button><form id="recovery-form"><label class="form-checkbox"><input type="checkbox" required name="saved">I have saved my recovery codes securely.</label><button class="btn navy large full" type="submit">Continue to dashboard ${icon('arrow',15)}</button></form>`;}
 if(S.auth==='enrol'||S.auth==='mfa'){
  const enrol=S.auth==='enrol';const qr=S.enrolment;
  return `<button class="back-link" data-action="logout">${icon('arrow',12)}Back to sign in</button><div class="auth-step"><i></i><i class="current"></i>STEP 2 OF 2</div><h1>${enrol?'Add your second layer.':'Confirm it\'s you.'}</h1><p class="intro">${enrol?'Set up two-factor authentication before entering your workspace.':'Enter the current code from your authenticator to open your workspace.'}</p>
  ${S.preview?'<div class="preview-mfa">'+icon('shield',36)+'<div><strong>Simulated two-factor step</strong><p>Use <b>123456</b> in this design preview only.<br>The full application uses a real authenticator.</p></div></div>':enrol?(qr?`<div class="qr-block"><img src="${esc(qr.qr)}" alt="Scan this QR code with your authenticator app"><div class="qr-steps"><p><b>1. Open your authenticator</b>Add a new account.</p><p><b>2. Scan this QR code</b>Keep the setup secret private.</p><p><b>3. Enter the code below</b>Codes change every 30 seconds.</p></div></div><details><summary>Cannot scan? Use a setup key</summary><div class="manual-key">${esc(qr.secret)}</div></details>`:'<div class="loading" style="min-height:130px">Preparing your authenticator...</div>'):''}
  <form id="mfa-form"><div class="field"><label for="mfa-code">${enrol?'Six-digit authenticator code':'Authenticator or recovery code'}</label><input id="mfa-code" class="${enrol?'code-input':''}" name="code" ${enrol?'inputmode="numeric" pattern="[0-9]{6}" maxlength="6"':'maxlength="50"'} autocomplete="one-time-code" required placeholder="${enrol?'000000':'Enter your code'}"></div><button type="submit" class="btn navy large full">Verify and continue ${icon('arrow',15)}</button></form><p class="auth-help">${icon('lock',12)}Your workspace remains locked until verification succeeds.</p>`;
 }
 return `<div class="auth-step"><i class="current"></i><i></i>STEP 1 OF 2</div><h1>Welcome to Real Estate Hub.</h1><p class="intro">Sign in to your CircleLogic workspace.<br>Your data. Your connections. Your clear view.</p>
 ${S.preview?'<div class="preview-auth-note"><strong>Interactive design preview</strong><br>This is not a secure login service. No real credentials or customer data should be entered.</div>':''}
 <form id="login-form">${field('username','Username','text','','autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Enter your username" maxlength="254"')}${field('password','Password','password','','autocomplete="current-password" placeholder="Enter your password" maxlength="256"')}<button class="btn navy large full" type="submit">Sign in ${icon('arrow',15)}</button></form>
 <p class="auth-help">Need access? <button class="text-btn" data-action="access-help">Contact your workspace administrator</button></p>
 ${(S.preview||S.environment!=='production')?'<div class="testing-note"><strong>Local testing account</strong><br>Username: <b>testing123</b><br>Password: <b>testing12345</b><br>For development only. Never use this shared login for a customer.</div>':''}`;
}
function renderAuth(){
 S.request++;$('#app').innerHTML=`<div class="auth-page"><section class="auth-left">${brand()}<div class="auth-story"><div class="eyebrow">REAL ESTATE HUB</div><h1>Less switching.<br>More perspective.</h1><p>A considered workspace for the systems you already use. Bring your real estate data, insights and activity into one clear view.</p><div class="architecture"><div class="architecture-center"><img src="/assets/circlelogic-logo.svg" alt="" width="33" height="33">Your connected workspace</div><div class="architecture-line"></div><div class="architecture-sources">${PROVIDERS.map(providerIcon).join('')}</div><div class="architecture-caption">Connect approved sources, at your pace.</div></div></div><div class="auth-left-foot">${icon('shield',13)}Built around workspace-specific access</div></section><section class="auth-right"><div class="auth-form-wrap">${authBody()}</div></section></div>`;
 if(S.auth==='enrol'&&!S.preview&&!S.enrolment){api('/auth/enrolment').then(data=>{if(S.auth==='enrol'){S.enrolment=data;renderAuth();}}).catch(e=>formError($('.auth-form-wrap'),e));}
}
async function loadSession(){const session=await api('/auth/session');S.session=session;S.csrf=session.csrf||'';S.environment=session.environment||'development';S.lastVerified=session.mfa_recent?Date.now():0;
 if(session.authenticated&&session.stage==='full'){S.user=session.user;S.auth='login';S.enrolment=null;return render();}
 S.user=null;S.auth=session.stage==='enrol'?'enrol':session.stage==='mfa'?'mfa':'login';return renderAuth();}
function ensureRecent(action){if(S.preview||Date.now()-S.lastVerified<9*60*1000)return action();
 S.pending=action;modal('Reverify your identity',`<p class="intro">Before changing credentials, enter a fresh authenticator code or an unused recovery code.</p><form id="stepup-form">${field('stepup','Authentication code','text','','autocomplete="one-time-code" maxlength="50"')}<button class="btn primary full" type="submit">Verify identity</button></form>`);
}
function openConnect(id){const c=providerById(id);if(!c)return;
 if(c.manageable===false){modal('Workspace access',`<p class="intro">Your role does not have permission to manage this connection. Ask a workspace owner or administrator to update your access.</p>`);return;}
 ensureRecent(()=>connectionDialog(c));
}
function connectionGuideLink(c){return window.BRAIN_GUIDES?.[c.id]?`<div class="key-guide"><button type="button" class="text-btn" data-action="guide" data-provider="${esc(c.id)}">${icon('file',15)}Setup guide ${icon('chevron',12)}</button></div>`:'';}
function connectionDialog(c){
 if(c.has_credentials&&!S.preview){
  const oauth=c.auth==='oauth';
  const calendarOAuth=c.id==='microsoft'||c.id==='google';
  const connectionOnly=!!c.connection_only;
  const intro=connectionOnly
   ? 'Connection details are saved for this provider. It is ready to be managed here and mapped into future workflows.'
   : oauth
    ? 'Continue to '+esc(c.name)+' to approve access, then sync.'
    : 'Save credentials and sync when you want to import data into the workspace.';
  modal(c.name,connectionGuideLink(c)+`<div class="connection-status-line">${statusMarkup(c.status)}<span class="muted small">${esc(relative(c.last_success))}</span></div>${c.error?'<div class="error-box">'+esc(c.error)+'</div>':''}<p class="intro">${intro}</p>${connectionOnly?'<div class="info-banner neutral">'+icon('check',18)+'<span>This connector can be managed here now. Data sync can be added later without changing the connection experience.</span></div>':`<div class="form-actions">${oauth?`<button class="btn" data-action="authorise" data-provider="${c.id}">Authorise ${esc(providerName(c.id))} ${icon('external',12)}</button>`:''}<button class="btn primary" data-action="sync" data-provider="${c.id}" ${oauth&&c.status==='configured'?'disabled':''}>${icon('refresh',14)}${calendarOAuth?'Test and sync':'Sync now'}</button></div>`}<div class="key-management"><button class="text-btn" data-action="replace-credentials" data-provider="${c.id}">Update connection</button>${connectionOnly?'':`<button class="text-btn" data-action="diagnostics" data-provider="${c.id}">Connection checks</button>`}<button class="text-btn" data-action="disconnect" data-provider="${c.id}">Disconnect</button></div>`);
  $('#active-dialog').classList.add('key-dialog');return;
 }
 credentialForm(c);
}
function compactKeyForm(c,help,label='Paste API key / client secret'){
 const disabled=S.preview?'disabled':'';
 modal(c.name,connectionGuideLink(c)+`<form id="credential-form" data-provider="${esc(c.id)}" data-mode="key" autocomplete="off">
 ${field('api_key',label,'password',help,`autocomplete="new-password" spellcheck="false" autocapitalize="none" maxlength="16000" data-lpignore="true" data-1p-ignore="true" ${disabled} placeholder="Paste your key here"`)}
 <div class="form-actions"><button type="submit" class="btn primary" ${disabled}>Save connection ${icon('arrow',14)}</button></div></form>`);
 $('#active-dialog').classList.add('key-dialog');
}
function fullCredentialForm(c){
 const disabled=S.preview?'disabled':'';
 const fields=(c.fields||[]).map(f=>field(f.key,f.label,f.secret?'password':'text',f.secret?'Saved securely.':'',`autocomplete="off" spellcheck="false" autocapitalize="none" maxlength="16000" ${disabled}`)).join('');
 modal(c.name,connectionGuideLink(c)+`<p class="intro">Add the approved credentials for ${esc(c.name)}. These values are stored securely for this workspace.</p><form id="credential-form" data-provider="${esc(c.id)}" data-mode="fields" autocomplete="off">${fields}<div class="form-actions"><button type="submit" class="btn primary" ${disabled}>Save connection ${icon('arrow',14)}</button></div></form>`);
 $('#active-dialog').classList.add('key-dialog');
}
function credentialForm(c){
 if(['microsoft','google','rea'].includes(c.id)){
  const help=S.preview?'Real keys are disabled in this preview.':c.id==='microsoft'?'Use the Microsoft client secret Value, not your CircleLogic password.':c.id==='google'?'Use the Google OAuth client secret from the same Web application as the saved client ID.':'Use your REA Partner Platform client secret, not your Ignite password.';
  return compactKeyForm(c,help);
 }
 if((c.fields||[]).length===1&&c.fields[0].key==='api_key')return compactKeyForm(c,'Use the approved API key or access token for this system.','Paste API key');
 return fullCredentialForm(c);
}
function setupGuideForm(c,setup){
 const fields=setup.fields.map(f=>field(f.key,f.label,'text','',`value="${esc(setup.values[f.key]||'')}" autocomplete="off" spellcheck="false" autocapitalize="none" maxlength="512"`)).join('');
 return `<section class="guide-setup"><h3>One-time connection setup</h3><p>Save these IDs once. Then paste only your client secret in the connection window. IDs are not passwords. Changing these IDs does not change an active connection until you save a key.</p><form id="connection-setup-form" data-provider="${esc(c.id)}" autocomplete="off">${fields}${setup.callback?`<div class="field"><label for="redirect-uri">${esc(c.name)} redirect URI</label><input id="redirect-uri" readonly value="${esc(setup.callback)}"><small>Copy this exact address into the provider's Web application credential. It is set by this server, not entered with your key.</small></div>`:''}<div class="form-actions"><button class="btn primary" type="submit">Save setup and paste key ${icon('arrow',14)}</button></div></form></section>`;
}
async function guide(id='agentbox'){
 S.guide=id;const g=window.BRAIN_GUIDES[id];if(!g)return;
 const c=S.connections.find(c=>c.id===id);let setup='',setupError='';
 if(!S.preview&&c?.implemented&&c.manageable){
  modal('Setup guide','<p class="intro">Opening your connection setup...</p>');const waiting=$('#active-dialog');
  try{const result=await api('/integrations/'+id+'/setup');if(!waiting.isConnected)return;setup=setupGuideForm(c,result);}
  catch(e){if(!waiting.isConnected)return;setupError='<div class="error-box" role="alert">'+esc(e.message)+'</div>';}
 }
 modal('Setup guide',`<div class="guide-tabs" aria-label="Provider guides">${PROVIDERS.map(p=>`<button class="${p===id?'active':''}" data-action="guide" data-provider="${p}">${esc(SHORT[p])}</button>`).join('')}</div><h2>${esc(g.title)}</h2><span class="guide-tag">${esc(g.tag)}</span><p class="guide-intro">${esc(g.intro)}</p>${setupError}${setup}<div class="guide-steps">${g.steps.map(([title,text],i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></div>`).join('')}</div><div class="info-banner neutral">${icon('info',18)}<span>${esc(g.note)}</span></div><div class="guide-sources"><h3>OFFICIAL PROVIDER GUIDANCE</h3>${g.links.map(([t,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(t)} ${icon('external',12)}</a>`).join('')}</div><p class="tiny-note">Provider pages behind sign-in were not inspected. These are access instructions, not fabricated screenshots of private vendor settings.</p><div class="form-actions"><button class="btn primary" data-action="guide-to-connect" data-provider="${id}">Back to ${esc(SHORT[id])}</button></div>`,true);
}

function openRecord(panel,index){const r=S.data?.[panel]?.rows?.[Number(index)];if(!r)return;
 let body=`<p class="intro">${S.example?'Fictional demonstration record. Not imported from any provider.':'Read-only record from the last successful import.'}</p><h3>${esc(r.title)}</h3>`;
 if(panel==='calendar'){body+=`<div class="detail-row"><span>Starts</span><strong>${esc(fmtDate(dateObj(r.start,r.timezone),{weekday:'long',day:'numeric',month:'long',year:'numeric',hour:'numeric',minute:'2-digit'}))}</strong></div><div class="detail-row"><span>Time zone</span><strong>Australia / Sydney</strong></div><div class="detail-row"><span>Location</span><strong>${esc(r.location||'Not provided')}</strong></div><div class="detail-row"><span>Visibility</span><strong>Private to this login</strong></div>`;}
 else if(S.example&&panel==='buyer_activity'){body+=`<div class="detail-row"><span>Example score</span><strong>${esc(r.score)} / 100</strong></div><div class="info-banner neutral" style="margin-top:19px">${icon('info',18)}<span>This score is illustrative. The real application does not calculate or import this score from listing-performance metrics.</span></div>`;}
 else body+=`<details class="inline-details" open><summary>Imported fields</summary><pre class="template">${safeJson(r)}</pre></details>`;
 modal(S.example?'Example record':'Imported record',body);
}
